-- Department store movements are inventory adjustments (INAJ), like the pharmacy's.
CREATE OR REPLACE FUNCTION fin_journal_code(p_source_type TEXT, p_source_id TEXT) RETURNS TEXT
LANGUAGE sql STABLE AS $$
  SELECT CASE WHEN p_source_type='CASH_VOUCHER' THEN COALESCE((SELECT CASE v.kind WHEN 'SPEND' THEN 'CDJ' WHEN 'RECEIVE' THEN 'CRJ' WHEN 'TRANSFER' THEN 'GENJ' END
              FROM fin_cash_vouchers v WHERE v.id::text = p_source_id), 'CDJ')
         ELSE CASE COALESCE(p_source_type, '') WHEN 'SALES_INVOICE' THEN 'SJ' WHEN 'CREDIT_NOTE' THEN 'SJ' WHEN 'CUSTOMER_RECEIPT' THEN 'CRJ' WHEN 'SUPPLIER_BILL' THEN 'PJ' WHEN 'DEBIT_NOTE' THEN 'PJ' WHEN 'PHARMACY_RECEIPT' THEN 'PJ' WHEN 'SUPPLIER_PAYMENT' THEN 'CDJ' WHEN 'CUSTOMER_REFUND' THEN 'CDJ' WHEN 'PAYROLL_PAYMENT' THEN 'CDJ' WHEN 'CASH_VOUCHER' THEN 'CDJ' WHEN 'DISPENSING' THEN 'COGS' WHEN 'DISPENSE_RETURN' THEN 'COGS' WHEN 'STOCK_ADJUSTMENT' THEN 'INAJ' WHEN 'STOCK_COUNT' THEN 'INAJ' WHEN 'STOCK_LOAN' THEN 'INAJ' WHEN 'STOCK_LOAN_RETURN' THEN 'INAJ' WHEN 'STOCK_LOAN_WRITEOFF' THEN 'INAJ' WHEN 'PHARMACY_ADJUST' THEN 'INAJ' WHEN 'DEPT_STOCK' THEN 'INAJ' WHEN 'FIXED_ASSET' THEN 'FA' WHEN 'DEPRECIATION_RUN' THEN 'FA' WHEN 'FIXED_ASSET_DISPOSAL' THEN 'FA' WHEN 'MANUAL_JOURNAL' THEN 'GENJ' WHEN 'MIGRATION' THEN 'GENJ' WHEN 'YEAR_END' THEN 'GENJ' WHEN 'PAYROLL' THEN 'GENJ' WHEN 'DATA_CORRECTION' THEN 'ADJ' ELSE 'GENJ' END END
$$;
